let risks = [];
let data;

try {
    data = JSON.parse($historical_invoices);
} catch (e) {
    return "ERROR: Could not parse historical invoice data. Ensure it is a valid JSON string.";
}

if (!Array.isArray(data) || data.length === 0) {
    return "PASS: Insufficient historical data to establish a pattern.";
}

let roundNumberCount = 0;
let weekendInvoices = 0;

data.forEach(invoice => {
    // 1. Check for Round Numbers (e.g., 5000, 10000, 25000)
    // Assuming amount is a property of the invoice object
    if (invoice.amount && invoice.amount % 1000 === 0) {
        roundNumberCount++;
    }

    // 2. Check for Unusual Timing (Weekends)
    // Assuming date is a property of the invoice object (format YYYY-MM-DD)
    if (invoice.date) {
        let dateObj = new Date(invoice.date);
        let dayOfWeek = dateObj.getDay(); // 0 is Sunday, 6 is Saturday
        if (dayOfWeek === 0 || dayOfWeek === 6) {
            weekendInvoices++;
        }
    }
});

if (roundNumberCount > (data.length * 0.3)) {
     risks.push(`High concentration of round-number invoices (${roundNumberCount} out of ${data.length}). This is a common indicator of fictitious billing.`);
}

if (weekendInvoices > 0) {
    risks.push(`${weekendInvoices} invoice(s) were submitted on a weekend. Verify the vendor's standard operating hours.`);
}

if (risks.length > 0) {
    return "PATTERN ANOMALIES DETECTED: " + risks.join(" | ");
} else {
    return "PASS: No significant statistical anomalies detected in the ledger history.";
}
